/*
 * Resolving the engine's ids out of the content tree.
 *
 * One table, read top to bottom. The point of keeping it in a single file is
 * that it is the complete list: if a number the engine sends is not derived
 * from something the player did, it is one of these, and it is here beside the
 * name the cache knows it by.
 */

#include "torirs_server_ids.h"

#include "torirs_server_content.h"

#include <stdio.h>

static struct ToriRSServerIds g_ids;

const struct ToriRSServerIds*
ToriRSServer_Ids(void)
{
    return &g_ids;
}

