const struct ToriRSServerSymbolRef*
ToriRSServer_IdsSymbols(int* out_count)
{
    *out_count = (int)(sizeof(k_refs) / sizeof(k_refs[0]));
    return k_refs;
}

int
ToriRSServer_IdsResolve(void)
{
    static const struct
    {
        const char* name;
        int* out;
    } k_constants[] = {
        { "bank_qty_1", &g_ids.bank_qty_1 },     { "bank_qty_5", &g_ids.bank_qty_5 },
        { "bank_qty_10", &g_ids.bank_qty_10 },   { "bank_qty_x", &g_ids.bank_qty_x },
        { "bank_qty_all", &g_ids.bank_qty_all },
        { "lootdrop_duration", &g_ids.lootdrop_duration },
    };
    int failed;

    failed = ToriRSServer_ContentResolve("ids", k_refs, (int)(sizeof(k_refs) / sizeof(k_refs[0])));

    for( size_t i = 0; i < sizeof(k_constants) / sizeof(k_constants[0]); i++ )
    {
        /* -1 rather than 0 for a missing one: a quantity mode of 0 is
         * "withdraw 1", so the fallback would be a working bank with the wrong
         * button lit. ToriRSServer_ContentConstantInt does the reporting. */
        *k_constants[i].out = ToriRSServer_ContentConstantInt(k_constants[i].name, -1);
        if( *k_constants[i].out < 0 )
            failed++;
    }

    if( failed )
        fprintf(stderr,
                "torirsserver: %d id(s) did not resolve — the content tree and the packs "
                "disagree\n",
                failed);
    return failed;
}
